            text = self.listen_and_convert()
            if text.lower() == 'exit':
                break

            translated_text = self.translate_text(text, target_lang)
            print(f"Original: {text}")
            print(f"Translated: {translated_text}")
            self.speak_text(translated_text)
            time.sleep(1)

